namespace ContentOS.Domain;

public abstract class CustomerRecord : CoreRecord { public Guid TenantId { get; set; } }
public sealed class CustomerUser : CustomerRecord { public bool AdultAttested { get; set; } public string LoginHash { get; set; } = ""; public string DisplayName { get; set; } = ""; public string State { get; set; } = "Active"; }
public sealed class CustomerIdentity : CustomerRecord { public Guid UserId { get; set; } public string Provider { get; set; } = ""; public string Account { get; set; } = ""; public string Environment { get; set; } = "Test"; public string SubjectHash { get; set; } = ""; public bool Enabled { get; set; } = true; }
public sealed class CustomerChallenge : CustomerRecord { public Guid UserId { get; set; } public string Provider { get; set; } = ""; public string Account { get; set; } = ""; public string Purpose { get; set; } = "Link"; public string ActorHash { get; set; } = ""; public DateTimeOffset ExpiresUtc { get; set; } public bool Used { get; set; } }
public sealed class CustomerHousehold : CustomerRecord { public string Label { get; set; } = ""; }
public sealed class CustomerMember : CustomerRecord { public Guid HouseholdId { get; set; } public Guid UserId { get; set; } public string Role { get; set; } = "Adult"; public bool Enabled { get; set; } = true; }
public sealed class CustomerInvite : CustomerRecord { public Guid HouseholdId { get; set; } public Guid UserId { get; set; } public string Role { get; set; } = "Adult"; public DateTimeOffset ExpiresUtc { get; set; } public bool Used { get; set; } }
public sealed class CustomerProfile : CustomerRecord { public Guid UserId { get; set; } public Guid HouseholdId { get; set; } public string Alias { get; set; } = ""; public string AgeBand { get; set; } = "Adult"; public string Locale { get; set; } = "en-IN"; public bool Personalization { get; set; } public bool Deleted { get; set; } }
public sealed class CustomerConsent : CustomerRecord { public Guid UserId { get; set; } public Guid? ProfileId { get; set; } public string Purpose { get; set; } = ""; public bool Granted { get; set; } public DateTimeOffset ExpiresUtc { get; set; } public string Evidence { get; set; } = ""; }
public sealed class CustomerProgress : CustomerRecord { public Guid ProfileId { get; set; } public string Key { get; set; } = ""; public int Position { get; set; } public bool Bookmark { get; set; } }
public sealed class CustomerProduct : CustomerRecord { public Guid? UniverseId { get; set; } public string RevenueStream { get; set; } = ""; public string Key { get; set; } = ""; public int Version { get; set; } public string Kind { get; set; } = "Credits"; public string Currency { get; set; } = "INR"; public long PriceMinor { get; set; } public long Credits { get; set; } public int Days { get; set; } public string FeaturesJson { get; set; } = "[]"; }
public sealed class CustomerPaymentRoute : CustomerRecord { public string Key { get; set; } = ""; public int Version { get; set; } public string Provider { get; set; } = ""; public string Account { get; set; } = ""; public string Environment { get; set; } = "Test"; public bool Enabled { get; set; } = true; public bool Active { get; set; } }
public sealed class CustomerPaymentBinding : CustomerRecord { public Guid UserId { get; set; } public string Provider { get; set; } = ""; public string Account { get; set; } = ""; public string Environment { get; set; } = "Test"; public string CustomerReference { get; set; } = ""; }
public sealed class CustomerOrder : CustomerRecord { public Guid UserId { get; set; } public Guid ProductId { get; set; } public Guid RouteId { get; set; } public Guid BindingId { get; set; } public string SnapshotJson { get; set; } = ""; public string Acquisition { get; set; } = "Unknown"; public string State { get; set; } = "Created"; public string? ExternalReference { get; set; } public string? SubscriptionReference { get; set; } public long Sequence { get; set; } public long RefundedMinor { get; set; } public DateTimeOffset? EndsUtc { get; set; } public DateTimeOffset? PaidUtc { get; set; } public Guid? Lease { get; set; } public DateTimeOffset? LeaseEndsUtc { get; set; } public string? RequestedAction { get; set; } }
public sealed class CustomerPaymentEvent : CustomerRecord { public Guid OrderId { get; set; } public Guid RouteId { get; set; } public string Provider { get; set; } = ""; public string Account { get; set; } = ""; public string Environment { get; set; } = "Test"; public string EventId { get; set; } = ""; public string Fingerprint { get; set; } = ""; public long Sequence { get; set; } public string EventJson { get; set; } = ""; }
public sealed class CustomerCredit : CustomerRecord { public Guid UserId { get; set; } public Guid? LotId { get; set; } public Guid? ReservationId { get; set; } public Guid? OrderId { get; set; } public string Kind { get; set; } = ""; public long Amount { get; set; } public DateTimeOffset? ExpiresUtc { get; set; } public string Evidence { get; set; } = ""; }
public sealed class CustomerReservation : CustomerRecord { public Guid UserId { get; set; } public Guid ProfileId { get; set; } public string UsageKey { get; set; } = ""; public DateTimeOffset ExpiresUtc { get; set; } public long Amount { get; set; } public string State { get; set; } = "Reserved"; public string? Provider { get; set; } public string? Account { get; set; } public string? Resource { get; set; } public long Consumed { get; set; } public string? OutcomeHash { get; set; } }
public sealed class CustomerNotification : CustomerRecord { public Guid UserId { get; set; } public Guid OrderId { get; set; } public string Key { get; set; } = ""; public string Kind { get; set; } = ""; public string Provider { get; set; } = "notification.inbox.v1"; public string State { get; set; } = "Pending"; public string? Receipt { get; set; } }
public sealed class CustomerCommand : CustomerRecord { public Guid OperationId { get; set; } public string ActorHash { get; set; } = ""; public string Kind { get; set; } = ""; public string Fingerprint { get; set; } = ""; public string ResultJson { get; set; } = ""; }
